import { writeFileSync } from 'node:fs';
import { audioClips } from '../src/data/course.ts';

const { sounds, words, hindi } = audioClips();

const lines = [
  '# Audio clips to record',
  '',
  'Generated by `npm run clips`. Do not edit by hand.',
  '',
  'Record in a quiet room, one MP3 per line, using exactly these file names.',
  'Speak slowly and clearly, the way you would to a small child, because recorded clips play exactly as recorded.',
  'Add a clip and the app uses it automatically. Until then it uses the device voice.',
  '',
  `## Pure sounds (${sounds.length} clips, in src/audio/phonics/)`,
  '',
  'Say only the sound, with no extra "uh": /s/ is "sss", not "suh". `th-voiced` is the sound in "this", and `th` is the sound in "bath".',
  '',
  ...sounds.map((s) => `- ${s}.mp3`),
  '',
  `## Whole words (${words.length} clips, in src/audio/words/)`,
  '',
  ...words.map((w) => `- ${w}.mp3`),
  '',
  `## Hindi letters and words (${hindi.length} clips, in src/audio/hindi/)`,
  '',
  ...hindi.map((w) => `- ${w}.mp3`),
  '',
];

writeFileSync('docs/audio-clips.md', lines.join('\n'));
console.log(`${sounds.length} sounds, ${words.length} words, ${hindi.length} Hindi clips`);
